Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
scsi: qla2xxx: Fix ISP recovery on unload

During unload process, the chip can encounter problem where a FW dump would
be captured. For this case, the full reset sequence will be skip to bring
the chip back to full operational state.

Fixes: e315cd28b9ef ("[SCSI] qla2xxx: Code changes for qla data structure refactoring")
Cc: <stable@vger.kernel.org>
Signed-off-by: Quinn Tran <quinn.tran@cavium.com>
Signed-off-by: Himanshu Madhani <himanshu.madhani@cavium.com>
Signed-off-by: Martin K. Petersen <martin.petersen@oracle.com>

Here is the root cause:
The bug occurs during the unload process of the SCSI driver for the qla2xxx series, where the chip may encounter a situation that requires a firmware dump. In this scenario, the original code would attempt to perform an ISP abort without considering whether the system was in the process of unloading, potentially leading to an incomplete or erroneous state of the chip. This could disrupt the recovery process and prevent the chip from returning to a fully operational state.

Here is the patch:
 **************************************************************************/
 static int
 qla2x00_do_dpc(void *data)
 {
 	scsi_qla_host_t *base_vha;
 	struct qla_hw_data *ha;
 	uint32_t online;
 	struct qla_qpair *qpair;

 	ha = (struct qla_hw_data *)data;
 	base_vha = pci_get_drvdata(ha->pdev);

 	set_user_nice(current, MIN_NICE);

 	set_current_state(TASK_INTERRUPTIBLE);
 	while (!kthread_should_stop()) {
 		ql_dbg(ql_dbg_dpc, base_vha, 0x4000,
 		    "DPC handler sleeping.\n");

 		schedule();

 		if (!base_vha->flags.init_done || ha->flags.mbox_busy)
 			goto end_loop;

 		if (ha->flags.eeh_busy) {
 			ql_dbg(ql_dbg_dpc, base_vha, 0x4003,
 			    "eeh_busy=%d.\n", ha->flags.eeh_busy);
 			goto end_loop;
 		}

 		ha->dpc_active = 1;

 		ql_dbg(ql_dbg_dpc + ql_dbg_verbose, base_vha, 0x4001,
 		    "DPC handler waking up, dpc_flags=0x%lx.\n",
 		    base_vha->dpc_flags);

 		if (test_bit(UNLOADING, &base_vha->dpc_flags))
 			break;

 		if (IS_P3P_TYPE(ha)) {
 			if (IS_QLA8044(ha)) {
 				if (test_and_clear_bit(ISP_UNRECOVERABLE,
 					&base_vha->dpc_flags)) {
 					qla8044_idc_lock(ha);
 					qla8044_wr_direct(base_vha,
 						QLA8044_CRB_DEV_STATE_INDEX,
 						QLA8XXX_DEV_FAILED);
 					qla8044_idc_unlock(ha);
 					ql_log(ql_log_info, base_vha, 0x4004,
 						"HW State: FAILED.\n");
 					qla8044_device_state_handler(base_vha);
 					continue;
 				}

 			} else {
 				if (test_and_clear_bit(ISP_UNRECOVERABLE,
 					&base_vha->dpc_flags)) {
 					qla82xx_idc_lock(ha);
 					qla82xx_wr_32(ha, QLA82XX_CRB_DEV_STATE,
 						QLA8XXX_DEV_FAILED);
 					qla82xx_idc_unlock(ha);
 					ql_log(ql_log_info, base_vha, 0x0151,
 						"HW State: FAILED.\n");
 					qla82xx_device_state_handler(base_vha);
 					continue;
 				}
 			}

 			if (test_and_clear_bit(FCOE_CTX_RESET_NEEDED,
 				&base_vha->dpc_flags)) {

 				ql_dbg(ql_dbg_dpc, base_vha, 0x4005,
 				    "FCoE context reset scheduled.\n");
 				if (!(test_and_set_bit(ABORT_ISP_ACTIVE,
 					&base_vha->dpc_flags))) {
 					if (qla82xx_fcoe_ctx_reset(base_vha)) {
 						/* FCoE-ctx reset failed.
 						 * Escalate to chip-reset
 						 */
 						set_bit(ISP_ABORT_NEEDED,
 							&base_vha->dpc_flags);
 					}
 					clear_bit(ABORT_ISP_ACTIVE,
 						&base_vha->dpc_flags);
 				}

 				ql_dbg(ql_dbg_dpc, base_vha, 0x4006,
 				    "FCoE context reset end.\n");
 			}
 		} else if (IS_QLAFX00(ha)) {
 			if (test_and_clear_bit(ISP_UNRECOVERABLE,
 				&base_vha->dpc_flags)) {
 				ql_dbg(ql_dbg_dpc, base_vha, 0x4020,
 				    "Firmware Reset Recovery\n");
 				if (qlafx00_reset_initialize(base_vha)) {
 					/* Failed. Abort isp later. */
 					if (!test_bit(UNLOADING,
 					    &base_vha->dpc_flags)) {
 						set_bit(ISP_UNRECOVERABLE,
 						    &base_vha->dpc_flags);
 						ql_dbg(ql_dbg_dpc, base_vha,
 						    0x4021,
 						    "Reset Recovery Failed\n");
 					}
 				}
 			}

 			if (test_and_clear_bit(FX00_TARGET_SCAN,
 				&base_vha->dpc_flags)) {
 				ql_dbg(ql_dbg_dpc, base_vha, 0x4022,
 				    "ISPFx00 Target Scan scheduled\n");
 				if (qlafx00_rescan_isp(base_vha)) {
 					if (!test_bit(UNLOADING,
 					    &base_vha->dpc_flags))
 						set_bit(ISP_UNRECOVERABLE,
 						    &base_vha->dpc_flags);
 					ql_dbg(ql_dbg_dpc, base_vha, 0x401e,
 					    "ISPFx00 Target Scan Failed\n");
 				}
 				ql_dbg(ql_dbg_dpc, base_vha, 0x401f,
 				    "ISPFx00 Target Scan End\n");
 			}
 			if (test_and_clear_bit(FX00_HOST_INFO_RESEND,
 				&base_vha->dpc_flags)) {
 				ql_dbg(ql_dbg_dpc, base_vha, 0x4023,
 				    "ISPFx00 Host Info resend scheduled\n");
 				qlafx00_fx_disc(base_vha,
 				    &base_vha->hw->mr.fcport,
 				    FXDISC_REG_HOST_INFO);
 			}
 		}

 		if (test_and_clear_bit(DETECT_SFP_CHANGE,
 			&base_vha->dpc_flags) &&
 		    !test_bit(ISP_ABORT_NEEDED, &base_vha->dpc_flags)) {
 			qla24xx_detect_sfp(base_vha);

 			if (ha->flags.detected_lr_sfp !=
 			    ha->flags.using_lr_setting)
 				set_bit(ISP_ABORT_NEEDED, &base_vha->dpc_flags);
 		}

-		if (test_and_clear_bit(ISP_ABORT_NEEDED,
-						&base_vha->dpc_flags)) {
+		if (test_and_clear_bit
+		    (ISP_ABORT_NEEDED, &base_vha->dpc_flags) &&
+		    !test_bit(UNLOADING, &base_vha->dpc_flags)) {

 			ql_dbg(ql_dbg_dpc, base_vha, 0x4007,
 			    "ISP abort scheduled.\n");
 			if (!(test_and_set_bit(ABORT_ISP_ACTIVE,
 			    &base_vha->dpc_flags))) {

 				if (ha->isp_ops->abort_isp(base_vha)) {
 					/* failed. retry later */
 					set_bit(ISP_ABORT_NEEDED,
 					    &base_vha->dpc_flags);
 				}
 				clear_bit(ABORT_ISP_ACTIVE,
 						&base_vha->dpc_flags);
 			}

 			ql_dbg(ql_dbg_dpc, base_vha, 0x4008,
 			    "ISP abort end.\n");
 		}

 		if (test_and_clear_bit(FCPORT_UPDATE_NEEDED,
 		    &base_vha->dpc_flags)) {
 			qla2x00_update_fcports(base_vha);
 		}

 		if (IS_QLAFX00(ha))
 			goto loop_resync_check;

 		if (test_bit(ISP_QUIESCE_NEEDED, &base_vha->dpc_flags)) {
 			ql_dbg(ql_dbg_dpc, base_vha, 0x4009,
 			    "Quiescence mode scheduled.\n");
 			if (IS_P3P_TYPE(ha)) {
 				if (IS_QLA82XX(ha))
 					qla82xx_device_state_handler(base_vha);
 				if (IS_QLA8044(ha))
 					qla8044_device_state_handler(base_vha);
 				clear_bit(ISP_QUIESCE_NEEDED,
 				    &base_vha->dpc_flags);
 				if (!ha->flags.quiesce_owner) {
 					qla2x00_perform_loop_resync(base_vha);
 					if (IS_QLA82XX(ha)) {
 						qla82xx_idc_lock(ha);
 						qla82xx_clear_qsnt_ready(
 						    base_vha);
 						qla82xx_idc_unlock(ha);
 					} else if (IS_QLA8044(ha)) {
 						qla8044_idc_lock(ha);
 						qla8044_clear_qsnt_ready(
 						    base_vha);
 						qla8044_idc_unlock(ha);
 					}
 				}
 			} else {
 				clear_bit(ISP_QUIESCE_NEEDED,
 				    &base_vha->dpc_flags);
 				qla2x00_quiesce_io(base_vha);
 			}
 			ql_dbg(ql_dbg_dpc, base_vha, 0x400a,
 			    "Quiescence mode end.\n");
 		}

 		if (test_and_clear_bit(RESET_MARKER_NEEDED,
 				&base_vha->dpc_flags) &&
 		    (!(test_and_set_bit(RESET_ACTIVE, &base_vha->dpc_flags)))) {

 			ql_dbg(ql_dbg_dpc, base_vha, 0x400b,
 			    "Reset marker scheduled.\n");
 			qla2x00_rst_aen(base_vha);
 			clear_bit(RESET_ACTIVE, &base_vha->dpc_flags);
 			ql_dbg(ql_dbg_dpc, base_vha, 0x400c,
 			    "Reset marker end.\n");
 		}

 		/* Retry each device up to login retry count */
 		if (test_bit(RELOGIN_NEEDED, &base_vha->dpc_flags) &&
 		    !test_bit(LOOP_RESYNC_NEEDED, &base_vha->dpc_flags) &&
 		    atomic_read(&base_vha->loop_state) != LOOP_DOWN) {

 			if (!base_vha->relogin_jif ||
 			    time_after_eq(jiffies, base_vha->relogin_jif)) {
 				base_vha->relogin_jif = jiffies + HZ;
 				clear_bit(RELOGIN_NEEDED, &base_vha->dpc_flags);

 				ql_dbg(ql_dbg_disc, base_vha, 0x400d,
 				    "Relogin scheduled.\n");
 				qla24xx_post_relogin_work(base_vha);
 			}
 		}
 loop_resync_check:
 		if (test_and_clear_bit(LOOP_RESYNC_NEEDED,
 		    &base_vha->dpc_flags)) {

 			ql_dbg(ql_dbg_dpc, base_vha, 0x400f,
 			    "Loop resync scheduled.\n");

 			if (!(test_and_set_bit(LOOP_RESYNC_ACTIVE,
 			    &base_vha->dpc_flags))) {

 				qla2x00_loop_resync(base_vha);

 				clear_bit(LOOP_RESYNC_ACTIVE,
 						&base_vha->dpc_flags);
 			}

 			ql_dbg(ql_dbg_dpc, base_vha, 0x4010,
 			    "Loop resync end.\n");
 		}

 		if (IS_QLAFX00(ha))
 			goto intr_on_check;

 		if (test_bit(NPIV_CONFIG_NEEDED, &base_vha->dpc_flags) &&
 		    atomic_read(&base_vha->loop_state) == LOOP_READY) {
 			clear_bit(NPIV_CONFIG_NEEDED, &base_vha->dpc_flags);
 			qla2xxx_flash_npiv_conf(base_vha);
 		}

 intr_on_check:
 		if (!ha->interrupts_on)
 			ha->isp_ops->enable_intrs(ha);

 		if (test_and_clear_bit(BEACON_BLINK_NEEDED,
 					&base_vha->dpc_flags)) {
 			if (ha->beacon_blink_led == 1)
 				ha->isp_ops->beacon_blink(base_vha);
 		}

 		/* qpair online check */
 		if (test_and_clear_bit(QPAIR_ONLINE_CHECK_NEEDED,
 		    &base_vha->dpc_flags)) {
 			if (ha->flags.eeh_busy ||
 			    ha->flags.pci_channel_io_perm_failure)
 				online = 0;
 			else
 				online = 1;

 			mutex_lock(&ha->mq_lock);
 			list_for_each_entry(qpair, &base_vha->qp_list,
 			    qp_list_elem)
 			qpair->online = online;
 			mutex_unlock(&ha->mq_lock);
 		}

 		if (test_and_clear_bit(SET_ZIO_THRESHOLD_NEEDED, &base_vha->dpc_flags)) {
 			ql_log(ql_log_info, base_vha, 0xffffff,
 				"nvme: SET ZIO Activity exchange threshold to %d.\n",
 						ha->nvme_last_rptd_aen);
 			if (qla27xx_set_zio_threshold(base_vha, ha->nvme_last_rptd_aen)) {
 				ql_log(ql_log_info, base_vha, 0xffffff,
 					"nvme: Unable to SET ZIO Activity exchange threshold to %d.\n",
 						ha->nvme_last_rptd_aen);
 			}
 		}

 		if (!IS_QLAFX00(ha))
 			qla2x00_do_dpc_all_vps(base_vha);

 		ha->dpc_active = 0;
 end_loop:
 		set_current_state(TASK_INTERRUPTIBLE);
 	} /* End of while(1) */
 	__set_current_state(TASK_RUNNING);

 	ql_dbg(ql_dbg_dpc, base_vha, 0x4011,
 	    "DPC handler exiting.\n");

 	/*
 	 * Make sure that nobody tries to wake us up again.
 	 */
 	ha->dpc_active = 0;

 	/* Cleanup any residual CTX SRBs. */
 	qla2x00_abort_all_cmds(base_vha, DID_NO_CONNECT << 16);

 	return 0;
 }



